<script setup>import { onMounted, ref } from 'vue'; import PageHero from '../components/PageHero.vue'; import Timeline from '../components/Timeline.vue'; import { fetchHistoryEvents } from '../api/history.js'; import { images } from '../data/imageAssets'; import { toDisplayImageUrl } from '../utils/imageUrl.js'
const events=ref([]);const loading=ref(true);const failed=ref(false)
onMounted(async()=>{try{const result=await fetchHistoryEvents({page:1,pageSize:100});events.value=result.list.map((item)=>({...item,year:item.timeText,date:'',description:item.summary,image:toDisplayImageUrl(item.coverImage)||images.historyPaper}))}catch{failed.value=true}finally{loading.value=false}})
</script>
<template><PageHero title="峥嵘岁月" description="已审核公开历史资料时间线。" :image="images.historyPaper" /><section class="section"><div class="shell"><div v-if="loading" class="empty-state">历史资料加载中…</div><div v-else-if="failed" class="empty-state">历史资料暂时无法加载，请稍后重试。</div><div v-else-if="events.length" style="margin-top:38px"><Timeline :events="events" /></div><div v-else class="empty-state">暂无已审核公开的历史资料。</div></div></section></template>
